    "titulo": "Plan y números",
    "html": "<section style=\"background:#151515;color:#F4F4F4\"><video class=\"pm-reel f\" style=\"left:1060px;top:150px;width:260px;height:462px;transform:rotate(-4deg);--d:1\" src=\"/clients/jansana/preview.mp4\" poster=\"/clients/jansana/poster.jpg\" autoplay muted loop playsinline preload=\"auto\"></video><video class=\"pm-reel f\" style=\"left:1350px;top:330px;width:260px;height:462px;transform:rotate(3deg);--d:2\" src=\"/clients/daddies/preview.mp4\" poster=\"/clients/daddies/poster.jpg\" autoplay muted loop playsinline preload=\"auto\"></video><video class=\"pm-reel f\" style=\"left:1620px;top:100px;width:260px;height:462px;transform:rotate(-2deg);--d:3\" src=\"/clients/macchina/preview.mp4\" poster=\"/clients/macchina/poster.jpg\" autoplay muted loop playsinline preload=\"auto\"></video><p class=\"abs a disp outline\" style=\"left:110px;top:140px;font-size:300px;--d:0\">06</p><p class=\"abs a pm-eyebrow\" style=\"left:128px;top:500px;--d:1\">Capítulo seis</p><h2 class=\"abs a disp\" style=\"left:128px;top:550px;width:880px;font-size:72px;line-height:1.05;--d:2\">Plan y<br>números</h2><p class=\"abs a soft\" style=\"left:128px;top:770px;width:820px;font-size:30px;line-height:1.4;--d:3\">Hoja de ruta, indicadores y lo que hacemos en los próximos 90 días.</p><div class=\"foot\"><img src=\"/maen-logo.png\" alt=\"Maen Studios\"><span>Business Plan 2027</span><span class=\"n\">25</span></div></section>"
